const $=s=>document.querySelector(s),E=FluxEngine;
const labels={none:'Aucun',minor:'Mineur',major:'Majeur',critical:'Critique'},roles={mechanic:'Garagiste',owner:'Responsable constructeur',recycler:'Centre de tri'};
let db,view='passport',selected=new URLSearchParams(location.search).get('battery')||'BP-004',role='mechanic',api=false,user=null,weights={...E.defaults};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>db.batteries.find(b=>b.id===selected)||db.batteries[0];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function save(){if(!api){try{localStorage.setItem('flux-v2',JSON.stringify(db));}catch{toast('Sauvegarde locale indisponible.');}}}
function event(b,title,detail){b.events.push({id:(crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('')),at:new Date().toISOString(),actor:roles[role],title,detail});b.revision++;}
async function request(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){const err=Error(d.error||'Erreur serveur');err.status=r.status;throw err;}return d;}
async function mutate(action,payload={}){const b=current();try{if(api){const result=await request('/api/batteries/'+b.id+'/'+action,{...payload,revision:b.revision});db.batteries[db.batteries.findIndex(x=>x.id===b.id)]=result;}else apply(b,action,payload);save();render();toast('Modification enregistrée dans '+(api?'Neo4j.':'la démonstration locale.'));}catch(e){toast(e.message);}}
function apply(b,action,p){if(action==='diagnostic'){if(role!=='mechanic'||b.stage!==0)throw Error('Diagnostic réservé au garagiste avant signalement.');E.validateDiagnostic(p);Object.assign(b,p);b.diagnostic={at:new Date().toISOString(),note:p.note};b.stage=1;event(b,'Diagnostic transmis',p.note||'Demande de passage à Waste envoyée au constructeur.');}else if(action==='waste'){if(role!=='owner'||b.stage!==1)throw Error('Action réservée au constructeur après diagnostic.');b.status='Waste';b.stage=2;event(b,'Statut Original → Waste','Validation du responsable constructeur.');}else if(action==='transfer'){if(role!=='owner'||b.stage!==2)throw Error('La batterie doit être Waste avant transfert.');if(!p.destination?.trim())throw Error('Centre destinataire requis.');b.transfer={destination:p.destination.trim(),at:new Date().toISOString()};b.stage=3;event(b,'Transfert enregistré',b.transfer.destination);}else if(action==='receive'){if(role!=='recycler'||b.stage!==3||b.status!=='Waste')throw Error('Réception impossible avant transfert et statut Waste.');b.stage=4;event(b,'Réception confirmée','Statut Waste vérifié par le centre de tri.');}else if(action==='inspection'){if(role!=='recycler'||b.stage!==4)throw Error('Inspection réservée au centre de tri après réception.');E.validateDiagnostic(p);Object.assign(b,p);b.inspected=true;event(b,'Inspection du centre de tri',p.note||'Diagnostic visuel et technique des cinq modules.');}else if(action==='decision'){if(role!=='recycler'||b.stage!==4||!b.inspected)throw Error('Réception et inspection du centre de tri requises.');const rec=E.recommend(b,p.weights,db.markets);const choice=rec.scores.find(s=>s.name===p.orientation&&s.eligible);if(!choice)throw Error('Orientation non admissible.');if(!p.justification?.trim())throw Error('Une justification humaine est requise.');b.decision={orientation:p.orientation,justification:p.justification,at:new Date().toISOString(),recommendation:rec,markets:structuredClone(db.markets),actor:roles[role]};b.stage=5;event(b,'Décision validée · '+p.orientation,p.justification);}else throw Error('Action inconnue');return b;}
function render(){const b=current();selected=b.id;const r=E.recommend(b,weights,db.markets);document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#role').value=role;$('#role').disabled=false;$('#role').title='Changer de compte';$('#breadcrumb').textContent={passport:'Passeports',decision:'Aide à la décision',history:'Traçabilité',guide:'Guide de démo'}[view];$('#title').textContent={passport:'Chaque batterie a une histoire.',decision:'La bonne décision, expliquée.',history:'Un parcours entièrement traçable.',guide:'Votre démo, prête à démarrer.'}[view];$('#subtitle').textContent={passport:'Suivez son parcours. Éclairez sa prochaine vie.',decision:'Quatre orientations. Des critères visibles. Une validation humaine.',history:'Du premier diagnostic à la décision du centre de tri.',guide:'Les rôles, le scénario et les ressources pour présenter le projet.'}[view];$('#stats').innerHTML=[['Passeports actifs',db.batteries.length,'5 modules par batterie'],['Diagnostics transmis',db.batteries.filter(x=>x.stage>=1).length,'Garagiste → constructeur'],['Batteries Waste',db.batteries.filter(x=>x.status==='Waste').length,'Statut vérifié avant réception'],['Décisions validées',db.batteries.filter(x=>x.decision).length,'Justification conservée']].map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1].toString().padStart(2,'0')}</strong><i>${x[2]}</i></div>`).join('');const q=$('#search').value.toLowerCase();const found=db.batteries.filter(x=>(x.id+x.model+x.owner).toLowerCase().includes(q));$('#resultcount').textContent=found.length+' batteries';$('#fleet').innerHTML=found.map(x=>`<button class="batteryitem ${x.id===b.id?'selected':''}" data-id="${x.id}"><strong>${esc(x.model)}</strong><small>${x.id} · ${esc(x.chemistry)} · SOH ${x.soh} %</small><br><span class="badge ${x.fault==='critical'?'red':x.status==='Waste'?'warn':''}">${x.status} ${x.decision?'· '+esc(x.decision.orientation):''}</span></button>`).join('')||'<p>Aucune batterie ne correspond à votre recherche.</p>';$('#content').innerHTML=view==='passport'?passport(b,r):view==='decision'?decision(b,r):view==='history'?historyView(b):guide();bind();}
function summary(b){return `<div class="card"><div class="cardtop"><div><div class="label">PASSEPORT NUMÉRIQUE / ${b.id}</div><h2>${esc(b.model)}</h2><span class="badge ${b.status==='Waste'?'warn':''}">${b.status}</span> <span class="badge ${b.fault==='critical'?'red':''}">Défaut ${labels[b.fault].toLowerCase()}</span></div><div class="batteryart" aria-hidden="true"></div></div><div class="metrics"><div><span class="label">État de santé</span><strong>${b.soh} %</strong></div><div><span class="label">Résistance</span><strong>${b.resistance} <small>mΩ</small></strong></div><div><span class="label">Âge</span><strong>${b.age} ans</strong></div></div><div class="facts"><div><span class="label">Responsable</span><span>${esc(b.owner)} / constructeur</span></div><div><span class="label">Chimie · capacité</span><span>${b.chemistry} · ${b.capacity} kWh</span></div><div><span class="label">Numéro de série</span><span>${b.serial}</span></div><div><span class="label">Cycles · révision</span><span>${b.cycles} cycles · v${b.revision}</span></div></div></div>`;}
function flow(b){return `<div class="card"><h3>Parcours de la batterie</h3><div class="flow">${['Original','Diagnostic','Waste','Transfert','Réception','Décision'].map((s,i)=>`<div class="step ${b.stage>=i?'done':''}">${s}</div>`).join('')}</div>${actionUI(b)}</div>`;}
function actionUI(b){if(role==='mechanic'&&b.stage===0)return `<div class="actionbox"><h3>Signaler une batterie hors d’usage</h3><p>Consignez le diagnostic puis demandez au constructeur le passage au statut Waste.</p>${diagnosticForm(b,'diagnostic')}</div>`;if(role==='owner'&&b.stage===1)return `<div class="actionbox"><h3>Demande du garagiste en attente</h3><p>${esc(b.diagnostic?.note)} Le responsable du passeport est le représentant du constructeur.</p><button class="primary" data-action="waste">Valider Original → Waste</button></div>`;if(role==='owner'&&b.stage===2)return `<form id="transfer"><label>Centre de tri destinataire<input name="destination" required maxlength="120" value="Centre de tri Hill Valley"></label><button class="primary">Enregistrer le transfert</button></form>`;if(role==='recycler'&&b.stage===3)return `<div class="actionbox"><h3>Réception au centre de tri</h3><p>${esc(b.transfer?.destination)} · Statut ${b.status} vérifié.</p><button class="primary" data-action="receive">Confirmer la réception</button></div>`;if(role==='recycler'&&b.stage===4)return `<div class="actionbox"><h3>Inspection visuelle et technique</h3><p>Renseignez les cinq modules avant de valider une orientation.</p>${diagnosticForm(b,'inspection')}<button class="outline" data-go="decision">Comparer les orientations →</button></div>`;if(b.stage===5)return `<div class="tip">Décision validée : <b>${esc(b.decision.orientation)}</b><br>${esc(b.decision.justification)}</div>`;return `<div class="actionbox"><p>Prochaine action : ${['diagnostic du garagiste','validation du constructeur','transfert par le constructeur','réception par le centre de tri','inspection et décision du centre de tri'][b.stage]}. ${api?'Connectez-vous avec le compte du rôle concerné.':'Reconnectez-vous avec le compte du rôle concerné.'}</p></div>`;}
function diagnosticForm(b,id){return `<form id="${id}"><div class="formgrid"><label>SOH du pack (%)<input name="soh" type="number" min="0" max="100" step="0.1" required value="${b.soh}"></label><label>Âge (années)<input name="age" type="number" min="0" max="40" step="0.1" required value="${b.age}"></label><label>Résistance pack (mΩ)<input name="resistance" type="number" min="0" max="10000" step="0.01" required value="${b.resistance}"></label><label>Référence résistance (mΩ)<input name="maxResistance" type="number" min="0.001" max="10000" step="0.001" required value="${b.maxResistance}"></label><label>Chimie<select name="chemistry">${['NMC','LFP'].map(s=>`<option ${b.chemistry===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Défaut du pack<select name="fault">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${b.fault===k?'selected':''}>${v}</option>`).join('')}</select></label></div><details><summary>Diagnostic des 5 modules</summary>${b.modules.map((m,i)=>`<fieldset><legend>Module ${i+1}</legend><div class="formgrid"><label>SOH (%)<input name="m${i}soh" type="number" min="0" max="100" step="0.1" value="${m.soh}" required></label><label>Résistance (mΩ)<input name="m${i}resistance" type="number" min="0" max="10000" step="0.01" value="${m.resistance}" required></label><label>Défaut<select name="m${i}fault">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${m.fault===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Constat visuel<input name="m${i}visual" maxlength="200" value="${esc(m.visual)}" required></label></div></fieldset>`).join('')}</details><label>Justification / constat<textarea name="note" required maxlength="1000" placeholder="Diagnostic visuel et technique…">${esc(id==='inspection'?'Inspection des modules : '+(b.fault==='critical'?'défaut critique confirmé, expertise spécialisée requise.':'diagnostic confirmé.'):b.fault==='none'?'Batterie déposée pour évaluation de fin de première vie.':'Défaut '+labels[b.fault].toLowerCase()+' constaté, batterie hors d’usage signalée.')}</textarea></label><button class="primary">${id==='inspection'?'Enregistrer l’inspection':'Transmettre le diagnostic'}</button></form>`;}
function recommendation(r){return `<div class="card recommend"><div class="label">DÉFI 03 / RECOMMANDATION</div><h2>${esc(r.title)}</h2><p>${esc(r.reason)}</p><p class="small" style="color:#c7d9d1">Règles pédagogiques · validation humaine obligatoire</p><button data-go="decision">Comprendre la recommandation ↗</button></div>`;}
function passport(b,r){return `<div class="grid"><section>${summary(b)}${flow(b)}<div class="card"><h3>Modules du pack</h3>${b.modules.map(m=>`<div class="score"><div class="scorehead"><span>${m.id} · ${labels[m.fault]}</span><b>${m.soh} %</b></div><div class="track"><i style="width:${m.soh}%"></i></div><small class="muted">${m.resistance} mΩ · ${esc(m.visual)}</small></div>`).join('')}</div></section><section>${recommendation(r)}<div class="card"><img class="qr" src="/qr/${b.id}.svg" alt="QR code du passeport ${b.id}"><h3>Accès au passeport</h3><p class="small">Scannez le QR code avec votre téléphone pour ouvrir cette batterie.</p><button class="outline" id="copy">Copier le lien</button><div style="clear:both"></div></div><div class="card"><h3>Derniers événements</h3>${timeline(b,3)}</div></section></div>`;}
function decision(b,r){return `<div class="grid"><section><div class="card"><div class="label">MATRICE MULTICRITÈRE / ${b.id}</div><h2>Comparer les quatre orientations</h2><p class="muted">Les exclusions techniques s’appliquent avant le classement. Les scores ne sont pas des probabilités.</p>${r.scores.map(s=>`<div class="actionbox" style="margin:12px 0"><div class="scorehead"><b>${s.name}</b><span>${s.eligible?s.score+' / 100':'Exclue'}</span></div><div class="track"><i style="width:${s.eligible?s.score:0}%;background:${s.eligible?'#174e42':'#ad6953'}"></i></div><div class="small">${s.eligible?'Admissible selon les règles de démonstration.':s.reasons.map(esc).join(' ')}</div><details><summary class="small">Voir le calcul et la demande</summary><p class="small">${Object.entries(s.criteria).map(([k,v])=>`${{health:'Technique',demand:'Marché',value:'Valeur',environment:'Environnement'}[k]} : ${v}/100 → ${s.contributions[k]} points`).join('<br>')}</p><p class="small">Demandes compatibles : ${s.markets.map(esc).join(', ')||'aucune'}</p></details></div>`).join('')}<div class="tip">Reuse : réemploi pour le même usage · Remanufacture : remise à neuf · Repurpose : changement d’usage · Recycle : récupération de matière.</div></div><div class="card"><h3>Demandes du marché</h3><p class="small">Catalogue pédagogique enregistré dans Neo4j. Lecture seule dans cette interface.</p>${db.markets.map((m,i)=>`<label style="display:block;margin:12px 0"><input type="checkbox" data-market="${i}" ${m.active?'checked':''} ${api?'disabled':''}> ${esc(m.name)} <span class="badge">${m.orientation} · urgence ${m.urgency}/100</span><br><small class="muted">SOH min. ${m.minSoh} % · ${m.chemistry||'toutes chimies'}</small></label>`).join('')}</div><div class="card"><h3>Valider une décision humaine</h3>${b.decision?`<div class="tip">${esc(b.decision.orientation)} — ${esc(b.decision.justification)}</div><p class="small">Pondérations et demandes utilisées conservées avec la décision.</p>`:role!=='recycler'||b.stage!==4||!b.inspected?'<p class="muted">Cette action nécessite le rôle centre de tri, une réception confirmée et une inspection enregistrée.</p><button class="outline" data-go="passport">Revenir au parcours</button>':`<form id="decision"><label>Orientation retenue<select name="orientation">${r.scores.filter(s=>s.eligible).map(s=>`<option>${s.name}</option>`).join('')}</select></label><label>Justification humaine<textarea name="justification" required maxlength="2000" placeholder="Expliquez votre choix et les critères retenus…"></textarea></label><button class="primary" ${r.blocked?'disabled':''}>Valider et tracer la décision</button></form>`}</div></section><section>${recommendation(r)}<div class="card"><h3>Pondérations configurables</h3><p class="small">Normalisées automatiquement par leur somme.</p><form id="weights">${Object.entries(weights).map(([k,v])=>`<label>${{health:'État technique',demand:'Demande du marché',value:'Valeur économique indicative',environment:'Bénéfice environnemental indicatif'}[k]}<input name="${k}" type="number" min="0" max="100" value="${v}" required></label>`).join('')}<button class="primary">Recalculer les scores</button></form></div><div class="card"><h3>Pourquoi ce résultat ?</h3><ul class="small">${r.rules.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="small">Aucune instruction de traitement physique n’est produite. Ces seuils ne constituent pas une certification technique.</p></div></section></div>`;}
function timeline(b,n=100){return b.events.slice(-n).reverse().map(e=>`<div class="event"><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><time>${new Date(e.at).toLocaleString('fr-FR')} · ${esc(e.actor)}</time></div>`).join('');}
function historyView(b){return `<div class="grid"><section>${summary(b)}<div class="card"><h3>Journal des événements</h3>${timeline(b)}</div></section><section><div class="card"><h3>Décision et éléments de preuve</h3>${b.decision?`<span class="badge">${esc(b.decision.orientation)}</span><p>${esc(b.decision.justification)}</p><p class="small">Règles ${esc(b.decision.recommendation.version)} · ${esc(b.decision.actor)}</p><button id="exportdecision" class="outline">Télécharger la décision JSON</button>`:'<p class="muted">Aucune décision validée pour cette batterie.</p>'}</div><div class="card"><h3>Export Neo4j</h3><p class="small">Le projet complet contient le schéma, les données et le serveur pour persister les événements et décisions dans Neo4j.</p><button class="outline" id="cypher">Exporter ce passeport en Cypher</button></div></section></div>`;}
function guide(){return `<div class="grid"><section><div class="card"><h2>Une démo en 3 minutes</h2><ol><li>Choisir <b>BP-003</b> et le rôle <b>Mécanicien</b>. Ouvrir le diagnostic des cinq modules puis transmettre.</li><li>Passer au <b>Responsable du passeport</b> : valider <b>Original → Waste</b> puis enregistrer le transfert.</li><li>Passer au <b>Recycleur</b> : confirmer la réception et enregistrer l’inspection.</li><li>Ouvrir <b>Aide à la décision</b>, comparer les quatre orientations et inspecter le calcul.</li><li>Changer les pondérations pour montrer leur influence sur le classement.</li><li>Justifier la décision, la valider puis consulter sa trace.</li></ol><div class="tip">Chaque rôle utilise son compte de démonstration. Le serveur contrôle les actions et conserve les données dans Neo4j Aura.</div><div class="actions"><a class="outline" href="presentation.html" target="_blank" rel="noopener">Ouvrir les 12 slides ↗</a><a class="outline" href="guide-deploiement.txt" download>Guide de déploiement ↓</a></div></div><div class="card"><h3>Les cinq cas de référence</h3>${db.batteries.map(b=>`<p><b>${b.id}</b> — ${esc(b.model)}<br><span class="small">Résultat attendu avec les données initiales : ${b.expected}.</span></p>`).join('')}<p class="small">Tests automatisés inclus pour vérifier ces résultats et les exclusions.</p></div></section><section><div class="card"><h3>Mode actuel</h3><p>${api?'Serveur connecté à Neo4j.':'Démonstration dans votre navigateur, sans connexion Neo4j.'}</p><p class="small">${api?'Les rôles sont vérifiés par le serveur.':'Les modifications sont conservées sur cet appareil. Changer de rôle simule les utilisateurs et ne constitue pas une authentification.'}</p>${api?'<button class="outline" id="logout">Changer de compte</button>':'<button class="outline" id="reset">Réinitialiser les données de démo</button>'}</div><div class="card"><h3>Périmètre</h3><p>Cas principal + défi 3 uniquement.</p><p class="small">Neo4j, 3 rôles, 5 batteries, 25 modules, 4 demandes du marché, moteur à pondérations, décisions justifiées, journal et exports.</p><p class="small">Pas de télémétrie, ni intégration PLM.</p></div></section></div>`;}
function download(name,obj,mime='application/json'){const u=URL.createObjectURL(new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:mime}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function diagnosticPayload(form){const f=new FormData(form),b=current(),p={};for(const k of ['soh','age','resistance','maxResistance'])p[k]=Number(f.get(k));for(const k of ['chemistry','fault','note'])p[k]=f.get(k);p.modules=b.modules.map((m,i)=>({...m,soh:Number(f.get('m'+i+'soh')),resistance:Number(f.get('m'+i+'resistance')),fault:f.get('m'+i+'fault'),visual:f.get('m'+i+'visual')}));return p;}
function bind(){document.querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>{selected=el.dataset.id;historyReplace();render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>mutate(el.dataset.action));document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>{view=el.dataset.go;render();});for(const type of ['diagnostic','inspection'])if($('#'+type))$('#'+type).onsubmit=e=>{e.preventDefault();mutate(type,diagnosticPayload(e.target));};if($('#transfer'))$('#transfer').onsubmit=e=>{e.preventDefault();mutate('transfer',{destination:new FormData(e.target).get('destination')});};if($('#weights'))$('#weights').onsubmit=e=>{e.preventDefault();const w=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));try{E.recommend(current(),w,db.markets);weights=w;render();toast('Scores recalculés.');}catch(err){toast(err.message);}};if($('#decision'))$('#decision').onsubmit=e=>{e.preventDefault();mutate('decision',{...Object.fromEntries(new FormData(e.target)),weights});};document.querySelectorAll('[data-market]').forEach(el=>el.onchange=()=>{db.markets[Number(el.dataset.market)].active=el.checked;save();render();});if($('#copy'))$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname+'?battery='+current().id);toast('Lien copié.');}catch{toast('Lien : '+location.origin+location.pathname+'?battery='+current().id);}};if($('#reset'))$('#reset').onclick=async()=>{if(!confirm('Réinitialiser les cinq batteries et effacer les décisions de cette démo ?'))return;db=await(await fetch('seed.json')).json();weights={...E.defaults};save();render();};if($('#logout'))$('#logout').onclick=async()=>{await request('/api/logout',{});location.reload();};if($('#exportdecision'))$('#exportdecision').onclick=()=>download(current().id+'-decision.json',current().decision);if($('#cypher'))$('#cypher').onclick=()=>{const b=current(),q=JSON.stringify(JSON.stringify(b));download(b.id+'.cypher',`MERGE (b:Battery {id: '${b.id}'})\nSET b.payload = ${q}, b.status = '${b.status}', b.revision = ${b.revision};\n`,'text/plain');};}
function historyReplace(){const u=new URL(location.href);u.searchParams.set('battery',selected);window.history.replaceState({},'',u);}
async function init(){api=true;try{const d=await request('/api/state');db=d;role=d.role;user=d.user;$('.live').textContent='● Connecté à Neo4j Aura';$('.sidefoot p').textContent='Données partagées dans Neo4j · rôles contrôlés par le serveur.';$('.role').firstChild.textContent='Compte connecté ';render();}catch(e){if(e.status===401){login();return;}throw e;}}
function login(preferredRole='mechanic',canCancel=false){
 const existing=$('#account-dialog');if(existing)existing.remove();
 const panel=document.createElement('dialog');panel.id='account-dialog';
 panel.innerHTML=`<form id="login"><h2>${canCancel?'Changer de compte':'Connexion au prototype'}</h2><p class="small">Choisissez votre compte puis saisissez le mot de passe du site.</p><label>Compte<select name="username">${Object.entries(roles).map(([key,label])=>`<option value="${key}" ${key===preferredRole?'selected':''}>${esc(label)} (${key})</option>`).join('')}</select></label><label>Mot de passe<input name="password" type="password" required autocomplete="current-password"></label><p id="loginerror" role="alert"></p><div class="actions">${canCancel?'<button class="outline" type="button" id="cancel-account">Annuler</button>':''}<button class="primary" type="submit">Se connecter</button></div></form>`;
 document.body.append(panel);
 panel.addEventListener('cancel',e=>{if(!canCancel)e.preventDefault();});
 panel.addEventListener('close',()=>panel.remove());
 panel.showModal();
 if(canCancel)$('#cancel-account').onclick=()=>panel.close();
 $('#login').onsubmit=async e=>{e.preventDefault();const button=panel.querySelector('button[type="submit"]');button.disabled=true;$('#loginerror').textContent='';try{
  await request('/api/login',Object.fromEntries(new FormData(e.target)));
  const d=await request('/api/state');db=d;role=d.role;user=d.user;
  $('.live').textContent='● Connecté à Neo4j Aura';
  $('.sidefoot p').textContent='Données partagées dans Neo4j · rôles contrôlés par le serveur.';
  $('.role').firstChild.textContent='Compte connecté ';
  panel.close();render();toast('Connecté : '+roles[role]);
 }catch(err){$('#loginerror').textContent=err.message;}finally{button.disabled=false;}};
}

document.querySelectorAll('nav button').forEach(el=>el.onclick=()=>{view=el.dataset.view;if(db)render();});$('#role').onchange=e=>{const targetRole=e.target.value;if(api){e.target.value=role;if(targetRole!==role)login(targetRole,true);}else{role=targetRole;render();}};$('#search').oninput=()=>{if(db)render();};$('#export').onclick=()=>{if(db)download(current().id+'-passport.json',current());};init().catch(e=>{$('#content').textContent='Chargement impossible : '+e.message;});
